companies = list_companies({})
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page })
    return result.items
}
contacts = fold acc = first.items for page in remaining { return acc + page }

# domain -> company name
domain_map = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

is_digit = fun(ch) {
    return ch == "0" or ch == "1" or ch == "2" or ch == "3" or ch == "4" or ch == "5" or ch == "6" or ch == "7" or ch == "8" or ch == "9"
}

# Process each contact
results = for contact in contacts {
    # Fix phone
    phone = contact.phone if contact.phone != null else ""
    phone_needs_fix = false
    new_phone = phone
    if phone != "" {
        # Check if already E.164 US: +1 followed by exactly 10 digits
        already_valid = regex.test(phone, "^\\+1[0-9]{10}$")
        if not already_valid {
            # Extract digits only
            digits = regex.replace(phone, "[^0-9]", "")
            # If 11 digits starting with 1, use last 10; if 10 digits, use them
            normalized = if text.length(digits) == 11 and text.starts_with(digits, "1") {
                return text.slice(digits, 1, 11)
            } else if text.length(digits) == 10 {
                return digits
            } else if text.length(digits) == 11 {
                return text.slice(digits, 1, 11)
            } else {
                return digits
            }
            if text.length(normalized) == 10 {
                new_phone = "+1" + normalized
                phone_needs_fix = true
            }
        }
    }

    # Fill company
    company_needs_fill = false
    new_company = contact.company if contact.company != null else ""
    company_empty = contact.company == null or contact.company == ""
    if company_empty and contact.email != null and contact.email != "" {
        parts = text.split(contact.email, "@")
        if list.length(parts) >= 2 {
            domain = parts[list.length(parts) - 1]
            if domain in domain_map {
                new_company = domain_map[domain]
                company_needs_fill = true
            }
        }
    }

    updated = false
    if phone_needs_fix or company_needs_fill {
        args = { id: contact.id }
        args_with_phone = args + { phone: new_phone } if phone_needs_fix else args
        args_final = args_with_phone + { company: new_company } if company_needs_fill else args_with_phone
        u = update_contact(args_final)
        updated = true
    }

    return {
        phone_fixed: phone_needs_fix,
        company_filled: company_needs_fill
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submit }

